      "clause_ids": ["POL-GEN-02"],
      "relies_on": "derived.arrival",
      "asserted_weight": 0.85
    },
    {
      "text": "The driver's arrival marker is a button press, not GPS_AUTO, so POL-NS-12 does not apply. The arrival must therefore be established under POL-NS-02 by at least three consecutive in-radius fixes with accuracy ≤25 m. The GPS trace is impaired, so the arrival evidence is discounted.",
      "evidence_ids": ["EV-TRIP-02736", "EV-GPS-02736"],
      "clause_ids": ["POL-NS-12", "POL-NS-02"],
      "relies_on": "platform_policy.arrival_marker",
      "asserted_weight": 0.85
    },
    {
      "text": "The rider's claim of presence is not contradicted by any clean evidence, because the rider's track is part of the impaired GPS artifact. Therefore, the rider's presence cannot be ruled out.",
      "evidence_ids": ["EV-GPS-02736"],
      "clause_ids": ["POL-GEN-02", "POL-NS-04"],
      "relies_on": "derived.rider_presence",
      "asserted_weight": 0.85
    }
  ]
}

